  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Prompting That Actually Works', 'The existing lessons show you which AI tools exist. This module teaches the skill that decides whether they are actually useful to you: how to ask.', v_module_offset + 1)
